import 'package:flutter/material.dart';import 'package:platform_core_frontend/features/super_admin/data/super_admin_repository.dart';import 'package:platform_core_frontend/features/super_admin/models/admin_masjid_model.dart';import 'package:platform_core_frontend/features/super_admin/presentation/masjids/widgets/admin_masjid_card.dart';import 'package:platform_core_frontend/features/super_admin/presentation/masjids/widgets/update_masjid_status_dialog.dart';import 'package:platform_core_frontend/shared/widgets/error_view.dart';import 'package:platform_core_frontend/shared/widgets/loading_view.dart';
class AdminMasjidsScreen extends StatefulWidget{const AdminMasjidsScreen({super.key,this.repository});final SuperAdminRepository? repository;@override State<AdminMasjidsScreen> createState()=>_S();}class _S extends State<AdminMasjidsScreen>{late final repo=widget.repository??SuperAdminRepository();String? status;String search='';late Future<AdminPage<AdminMasjidModel>> f=_load();Future<AdminPage<AdminMasjidModel>> _load()=>repo.getMasjids(search:search,status:status);void _refresh()=>setState(()=>f=_load());@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(labelText:'Search masjids'),onSubmitted:(v){search=v;_refresh();})),Wrap(spacing:8,children:[for(final s in [null,'PENDING','APPROVED','REJECTED','SUSPENDED'])FilterChip(label:Text(s??'ALL'),selected:status==s,onSelected:(_){status=s;_refresh();})]),Expanded(child:FutureBuilder(future:f,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const LoadingView();if(s.hasError)return ErrorView(title:'Unable to load',message:s.error.toString(),onRetry:_refresh);final items=s.data?.items??[];return RefreshIndicator(onRefresh:()async=>_refresh(),child:ListView(children:[for(final item in items)AdminMasjidCard(item:item,onStatus:()async{final st=await showUpdateMasjidStatusDialog(c);if(st!=null){try{await repo.updateMasjidStatus(item.id,st);_refresh();}catch(_){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Masjid status API is not available yet.')));}}}),if(items.isEmpty)const Padding(padding:EdgeInsets.all(32),child:Center(child:Text('No masjids found')))]));}))]);}
